import {lesson,respond} from './engine.js';
import {modes,catalog,material,buildPlan,analytics,makeQuiz} from './learning.js';
const $=s=>document.querySelector(s),main=$('#main');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID(),today=()=>new Date().toLocaleDateString('en-CA');
let state={events:[],sessions:[],materials:[],subjects:[],plan:[],hours:2,goals:[]},memory=false,me=null,config={live:false},page='home',mode='mentor',session=null,busy=false,room=null,roomPoll=null,notesVersion=0,notesDirty=false,quiz=null,flash=null,focus={seconds:1500,running:false,phase:'Focus',goal:'',topic:'',deadline:0};
try{memory=localStorage.getItem('mindmate-memory')==='true';if(memory){const saved=JSON.parse(localStorage.getItem('mindmate-data'));if(saved&&Array.isArray(saved.events)&&Array.isArray(saved.sessions))state={...state,...saved};}else if(localStorage.getItem('guideai-memory')==='true'){const old=JSON.parse(localStorage.getItem('guideai-data')||'{}');memory=true;state.sessions=(old.sessions||[]).map(s=>({...s,mode:'mentor',elapsed:0}));if(old.xp)state.events.push({id:'legacy',type:'legacy',xp:old.xp,at:Date.now()});localStorage.setItem('mindmate-memory','true');}}catch{}
function notify(message){$('#status').textContent=message;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#status').textContent='',6500);}
function save(){if(memory)try{localStorage.setItem('mindmate-data',JSON.stringify(state));}catch{notify('Storage is full. Export your data before closing.');}$('#xp').textContent=`✦ ${analytics(state.events).xp} XP`;$('#memory-status').textContent=`Personal memory is ${memory?'on · this browser':'off'}`;}
function event(type,detail={},id=uid()){if(state.events.some(e=>e.id===id))return;state.events.push({id,type,at:Date.now(),...detail});save();}
function saveSession(){if(!session)return;const i=state.sessions.findIndex(s=>s.id===session.id);if(i<0)state.sessions.unshift(session);else state.sessions[i]=session;state.sessions=state.sessions.slice(0,50);save();}
function download(name,content,type='text/plain'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function api(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(110000)});const out=await r.json();if(!r.ok)throw new Error(out.error||'Could not connect.');return out;}
async function task(fn){if(busy)return;busy=true;document.body.setAttribute('aria-busy','true');try{return await fn();}catch(e){notify(e.message||'Could not complete this action.');}finally{busy=false;document.body.removeAttribute('aria-busy');}}
function modal(html){$('#dialog-content').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal();}
function options(values,selected){return values.map(v=>`<option ${v===selected?'selected':''}>${esc(v)}</option>`).join('');}
function topicOptions(){return Object.entries(catalog).map(([k,c])=>`<option value="${k}">${c.subject} · ${c.name}</option>`).join('');}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
const select=(label,name,opts)=>`<label class="field">${label}<select name="${name}">${opts}</select></label>`;
function title(name,sub='',actions=''){return `<div class="topline"><div><div class="eyebrow">YOUR PERSONAL LEARNING COMPANION</div><h1>${name}</h1><p class="sub">${sub}</p></div><div class="actions">${actions}</div></div>`;}
function btn(label,action,cls='secondary'){return `<button class="${cls}" data-action="${action}">${label}</button>`;}
function form(id,handler){const f=$('#'+id);if(f)f.onsubmit=e=>{e.preventDefault();if(busy)return;handler(Object.fromEntries(new FormData(f)),f);};}
function enter(el){if(el)el.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();el.form.requestSubmit();}};}
function recordTime(){if(session?.activeAt){session.elapsed=(session.elapsed||0)+Math.min(300,Math.round((Date.now()-session.activeAt)/1000));session.activeAt=Date.now();saveSession();}}
function view(v){if(busy)return notify('Please wait for the current request.');recordTime();clearInterval(roomPoll);roomPoll=null;page=v;document.body.classList.toggle('focus-active',v==='focus'&&focus.running);document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#crumb').textContent=({home:'Dashboard',studio:'Learning studio',chat:'Learning studio / Conversation',practice:'Practice & quizzes',materials:'Study materials',planner:'Study planner',focus:'Focus mode',buddies:'Find a study buddy',rooms:'Study rooms',room:'Study room',progress:'Progress & insights',history:'Recent sessions',privacy:'Profile & privacy'})[v]||v;const routes={home,studio,chat,practice,materials,planner,focus:focusView,buddies,rooms,room:roomView,progress,history,privacy};routes[v]?.();window.scrollTo(0,0);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-view],[data-action],[data-mode],[data-topic]');if(!b)return;if(b.dataset.view)return view(b.dataset.view);if(b.dataset.mode)return switchMode(b.dataset.mode);if(b.dataset.topic)return startLesson(b.dataset.topic);const action=b.dataset.action;handle(action,b);});
$('#close-dialog').onclick=()=>$('#dialog').close();$('#help').onclick=()=>modal('<div class="eyebrow">LEARN YOUR WAY</div><h2>Meet your MindMate</h2><p><b>Teacher</b> explains a concept with an example.<br><b>Mentor</b> gives you room to think, one hint at a time.<br><b>Study buddy</b> revises, quizzes and practises with you.</p><p>Start a built-in lesson without API credits, or ask an open-ended question with live AI. Plan your week, track your progress and invite friends into a shared room.</p><p class="muted">AI can be wrong. Check important facts. Built-in answer checks cover a limited set of concepts.</p>');
function home(){const a=analytics(state.events),name=me?.profile?.name?.split(' ')[0]||'curious mind';main.innerHTML=title(`Hello, ${esc(name)} ✦`,'A little curiosity. A little practice. A little better every day.',`<span class="date-tag">${new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</span>`)+`<section class="hero"><div><div class="eyebrow">YOUR NEXT AHA! MOMENT STARTS HERE</div><h2>You don’t have to figure<br>it all out alone.</h2><p>A teacher when you need clarity. A mentor when you need a nudge.<br>A study buddy for the journey.</p>${btn('Let’s learn something ↗','studio','primary')}</div><div class="hero-art" aria-hidden="true">✳</div></section>${stats(a)}<div class="section-title"><h2>How would you like to learn?</h2><span class="muted">Three ways. One MindMate.</span></div><div class="grid">${Object.entries(modes).map(([k,m])=>`<button class="card mode-card" data-mode="${k}"><span class="card-icon">${m.icon}</span><h3>${m.label}</h3><p>${m.description}</p><span class="link">Meet your ${m.name.toLowerCase()} ↗</span></button>`).join('')}</div><div class="split"><section class="card"><div class="section-title" style="margin-top:0"><h2>Your next small win</h2><button data-view="planner">View planner →</button></div>${recommendations(a)}</section><section class="card"><h2>Better, together.</h2><p class="sub">Find someone working toward the same goal. Make a little progress, side by side.</p><div class="actions">${btn('Find a study buddy ↗','buddies','primary')}${btn('My study rooms','rooms')}</div></section></div>`;}
function stats(a){return `<div class="stats">${[['✦',a.xp,'XP earned'],['◷',a.minutes+' min','Focused study'],['◈',a.accuracy===null?'—':a.accuracy+'%','Quiz accuracy'],['♨',a.streak+' days','Study streak']].map(([i,n,l])=>`<div class="stat"><span class="stat-icon">${i}</span><div><strong>${n}</strong><small>${l}</small></div></div>`).join('')}</div>`;}
function recommendations(a){let rows=[];for(const [t,s]of Object.entries(a.topics))if(s.attempts>=2&&s.correct/s.attempts<.6)rows.push([`Revisit ${catalog[t]?.name||t}`,'Try a Teacher explanation, then three practice questions.','practice']);const due=state.plan.find(p=>!p.done&&p.date<=today());if(due)rows.push([due.subject,`${due.minutes} minutes · ${due.task}`,'planner']);for(const s of state.subjects){const days=Math.ceil((new Date(s.exam+'T00:00:00')-Date.now())/86400000);if(days>=0&&days<=14)rows.push([`${s.name} exam in ${days} days`,'Make time for revision and a short quiz.','planner']);}if(!rows.length)rows=[['Build your first learning streak','Start with one short guided lesson.','studio'],['Give your study time a purpose','Add an exam date and create a realistic plan.','planner']];return rows.slice(0,3).map(([h,p,v])=>`<div class="list-row"><span class="card-icon" style="margin:0">↗</span><div><strong>${esc(h)}</strong><small>${esc(p)}</small></div><button data-view="${v}" aria-label="Open ${esc(h)}">→</button></div>`).join('');}
function tabs(){return `<div class="mode-tabs">${Object.entries(modes).map(([k,m])=>`<button data-mode="${k}" class="${mode===k?'active':''}" aria-pressed="${mode===k}">${m.icon} ${m.name}</button>`).join('')}</div>`;}
function studio(){main.innerHTML=title('What are we learning today?','Choose how you learn. Switch modes whenever you need.')+tabs()+`<form id="ask" class="question"><label for="question" class="muted">Your question or concept</label><textarea id="question" name="question" maxlength="12000" placeholder="Ask a question, share a problem, or tell me what feels confusing…" required></textarea><div class="input-bottom"><button type="button" class="secondary" data-action="image">＋ Question from an image</button><span class="muted">${modes[mode].description}</span><button class="primary">Start learning ↗</button></div><input id="image-file" type="file" accept="image/png,image/jpeg,image/webp" hidden></form><div class="section-title"><h2>Built-in lessons · no API credits needed</h2></div><div class="grid">${Object.entries(catalog).map(([k,c])=>`<button class="card mode-card" data-topic="${k}"><span class="card-icon">${k==='algebra'?'𝑥':k==='science'?'↗':'⌘'}</span><span class="muted">${c.subject}</span><h3 style="margin-top:9px">${c.name}</h3><span class="link">Learn, practise, explain ↗</span></button>`).join('')}</div><div class="section-title"><h2>Coding & viva</h2></div><form id="coding" class="card form-grid">${select('Language','language',options(['C','C++','Python','Java','JavaScript','SQL','HTML','CSS']))}${select('Activity','activity',options(['Explain a concept','Guide my code','Practice with me','Viva / interview']))}<label class="field wide">Concept, question, or code<textarea name="prompt" required maxlength="10000" placeholder="For example: inheritance in Java, or a loop I can’t debug"></textarea></label><div class="actions wide"><button class="primary">Open coding tutor ↗</button><span class="muted">Live AI · code is explained, never executed</span></div></form>`;form('ask',d=>startQuestion(d.question));form('coding',d=>{if(d.activity==='Viva / interview')mode='viva';startQuestion(`${d.activity} in ${d.language}: ${d.prompt}`);});enter($('#question'));$('#image-file').onchange=upload;}
function switchMode(next){if(busy)return;if(!modes[next])return;mode=next;if(page==='chat'&&session){session.mode=mode;if(session.state){const c=catalog[session.state.topic];session.messages.push({role:'assistant',text:next==='teacher'?c.explanation+'\n\n'+c.example+'\n\nWhen you’re ready, switch to Mentor and try your problem.':next==='student'?'Let’s study together. Explain the key idea to me in your own words.':'Let’s work through your original problem one step at a time. '+session.state.hints[0]});session.state.teach=next==='student';}else session.messages.push({role:'assistant',text:`Switched to ${modes[next].name} mode. What would you like to work on next?`});saveSession();chat();}else view('studio');}
function startLesson(topic,difficulty=1){session={id:uid(),title:catalog[topic].name,date:new Date().toISOString(),mode,elapsed:0,activeAt:Date.now(),state:lesson(topic,difficulty),messages:[]};const c=catalog[topic];session.messages.push({role:'assistant',text:mode==='teacher'?c.explanation+'\n\n'+c.example+'\n\nYour turn: '+session.state.intro+'\nWhat do you already know about this?':session.state.intro+'\n\nBefore we begin, what do you already know about this topic?'});saveSession();view('chat');}
function startQuestion(text){if(!text.trim())return;session={id:uid(),title:text.slice(0,65),date:new Date().toISOString(),mode,elapsed:0,activeAt:Date.now(),state:null,messages:[]};view('chat');send(text);}
function chat(){if(!session)return view('studio');mode=session.mode||'mentor';const s=session.state;main.innerHTML=title(esc(session.title),s?'Built-in guided lesson · '+['Foundation','Core','Challenge'][s.difficulty-1]:'Live AI conversation',btn('Session summary','summary')+btn('New session','studio'))+(modes[mode]?tabs():'<span class="pill">Viva / interview</span>')+(s?`<div class="steps">${['Understand','Solve','Explain'].map((t,i)=>`<div class="step ${(i===0?s.stage>0:i===1?s.solved:s.taught)?'done':''}">${i+1} · ${t}</div>`).join('')}</div>`:'')+`<div id="messages" class="messages" role="log" aria-label="Learning conversation"></div>${s&&s.attempts>=2&&!s.solved&&mode==='mentor'?`<div class="notice">A clearer explanation might help. ${btn('Switch to Teacher','teacher')}</div>`:''}<div class="actions">${btn('☀ Hint','hint')}${btn('Show solution','solution')}${btn('↻ Similar practice','similar')}${btn('✧ Teach it back','teach')}${btn('Quick recap','recap')}</div><form id="attempt" class="question"><label for="answer" class="muted">${s?.teach?'Explain the idea in your own words':'Share your thinking, not just your answer'}</label><textarea id="answer" name="answer" required maxlength="10000" placeholder="Here’s what I’m thinking…"></textarea><div class="input-bottom"><span class="muted">Enter to send · Shift + Enter for a new line</span><button class="primary">Send ↗</button></div></form>`;messages();form('attempt',d=>send(d.answer));enter($('#answer'));}
function messages(){if(!$('#messages'))return;$('#messages').innerHTML=session.messages.map(m=>`<div class="message ${m.role==='user'?'user':esc(m.kind||'')}"><span class="sender">${m.role==='user'?'YOU':'✳ MINDMATE'}</span>${esc(m.text)}</div>`).join('');$('#messages').scrollTop=$('#messages').scrollHeight;}
async function send(text,action='attempt'){if(busy||!text.trim())return;const previous=session.messages.length;session.messages.push({role:'user',text});if($('#answer'))$('#answer').value='';messages();await task(async()=>{try{let reply;if(session.state){reply=respond(session.state,text,action);if(reply.xp)event(reply.xp===25?'teach':'solved',{xp:reply.xp,topic:session.state.topic},session.id+'-'+(reply.xp===25?'teach':'solved'));}else{notify('MindMate is thinking…');reply={text:(await api('/api/chat',{messages:session.messages,mode})).text};}session.messages.push({role:'assistant',...reply});recordTime();saveSession();chat();$('#answer')?.focus();if(!session.state)notify('Your response is ready.');}catch(e){session.messages.splice(previous);chat();$('#answer').value=text;throw e;}});}
function summary(){recordTime();const s=session.state;modal(`<div class="eyebrow">TODAY’S LEARNING</div><h2>${esc(session.title)}</h2><p>${Math.max(1,Math.round((session.elapsed||0)/60))} min in this session · ${session.messages.filter(m=>m.role==='user').length} contributions</p><p>${s?`${s.attempts} attempts · ${s.solved?'Problem completed':'Still practising'} · ${s.hint} hint requests<br>${s.taught?'Teach-back completed.':'Next: explain the concept in your own words.'}`:'Review your conversation and explain the main idea without looking at the answer.'}</p><p class="sub">${s&&!s.solved?'Recommended: revisit the concept in Teacher mode, then attempt a similar problem.':'Recommended: try another problem tomorrow to check what you remember.'}</p>${btn('Download session','download-session')}${!s?btn('Generate AI summary','ai-summary'):''}`);}
function practice(){main.innerHTML=title('Make understanding stick.','A small challenge today. More confidence tomorrow.')+`<form id="practice-setup" class="card form-grid">${select('Subject / built-in topic','topic',topicOptions())}${select('Difficulty','difficulty','<option value="1">Foundation</option><option value="2">Core</option><option value="3">Challenge</option>')}${select('Format','format',options(['MCQ quiz','Short answer','Problem solving','Coding problem','Application question','Viva question']))}${field('Custom topic (optional, uses live AI)','custom','','text','maxlength="150"')}<div class="actions wide"><button class="primary">Start practice ↗</button><span class="muted">MCQs and guided problems work offline. Custom formats use AI.</span></div></form><div id="quiz-area"></div>`;form('practice-setup',d=>{if(d.custom||['Coding problem','Application question','Viva question'].includes(d.format)){mode=d.format==='Viva question'?'viva':'mentor';return startQuestion(`Create a ${d.format} practice session about ${d.custom||catalog[d.topic].name} at ${['foundation','core','challenge'][+d.difficulty-1]} level. Ask one question, wait for my attempt, evaluate it and adapt difficulty.`);}if(d.format!=='MCQ quiz'){mode='mentor';return startLesson(d.topic,+d.difficulty);}quiz={id:uid(),topic:d.topic,index:0,correct:0,answers:[],questions:makeQuiz(d.topic,+d.difficulty)};renderQuiz();});}
function renderQuiz(){const c={...catalog[quiz.topic],questions:quiz.questions},q=c.questions[quiz.index];if(!q){$('#quiz-area').innerHTML=`<div class="card" style="margin-top:20px"><span class="eyebrow">PRACTICE COMPLETE</span><h2>${quiz.correct} / ${c.questions.length} correct</h2><p>${quiz.correct===c.questions.length?'Ready to stretch yourself? Try a guided problem at the next difficulty.':'Review the explanations below, then revisit the concept in Teacher mode.'}</p>${quiz.answers.map((a,i)=>`<p><b>${a.correct?'✓':'↻'} ${esc(c.questions[i][0])}</b><br>${esc(c.questions[i][3])}</p>`).join('')}${btn('Learn this concept','quiz-teacher')}${btn('View my progress','progress')}</div>`;return;}$('#quiz-area').innerHTML=`<div class="card" style="margin-top:20px"><span class="eyebrow">QUESTION ${quiz.index+1} OF ${c.questions.length}</span><h2>${q[0]}</h2>${q[1].map((o,i)=>`<button class="option" data-action="quiz-answer" data-index="${i}">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}<div id="quiz-feedback" role="status"></div></div>`;}
function quizAnswer(n){if(quiz.answers[quiz.index])return;const q=quiz.questions[quiz.index],correct=n===q[2];quiz.answers[quiz.index]={correct};if(correct)quiz.correct++;event('quiz',{topic:quiz.topic,correct,xp:correct?10:0},quiz.id+'-'+quiz.index);document.querySelectorAll('[data-action="quiz-answer"]').forEach((b,i)=>{b.disabled=true;b.classList.toggle('correct',i===q[2]);b.classList.toggle('wrong',i===n&&!correct);});$('#quiz-feedback').innerHTML=`<div class="notice">${correct?'✓ Correct.':'Let’s learn from this.'} ${q[3]}</div>${btn('Next question →','quiz-next','primary')}`;}
function materials(){main.innerHTML=title('Turn a topic into a study toolkit.','Create notes, flashcards and revision sheets, or bring your own material.')+`<form id="material-form" class="card form-grid">${select('Built-in topic','topic',topicOptions())}${select('Create','type',options(['Notes','Summary','Flashcards','Important questions','Revision sheet','Key concepts','Practice problems','Mind map','Topic explanation']))}${field('Custom subject / topic (optional)','custom','','text','maxlength="150"')}<label class="field">Or upload text / Markdown<input id="material-file" type="file" accept=".txt,.md,text/plain,text/markdown"></label><label class="field wide">Your material (optional; live AI)<textarea name="source" id="source" maxlength="12000" placeholder="Paste your notes or textbook extract here…"></textarea></label><div class="actions wide"><button class="primary">Create study material ↗</button><span class="muted">Built-in topics work offline. Custom material is sent to AI.</span></div></form><div id="material-result"></div><div class="section-title"><h2>Your saved toolkit</h2></div><div id="saved-materials">${state.materials.length?state.materials.map((m,i)=>`<button class="option" data-action="open-material" data-index="${i}">${esc(m.title)} <span class="muted">· ${new Date(m.at).toLocaleDateString()}</span></button>`).join(''):'<p class="empty">Your generated notes will appear here for this visit. Enable memory to keep them.</p>'}</div>`;form('material-form',d=>task(async()=>{let output;if(d.custom||d.source){notify('Creating your study material…');output=(await api('/api/chat',{mode:'teacher',messages:[{role:'user',text:`Create a ${d.type} for ${d.custom||catalog[d.topic].name}. ${d.source?'Use only the following source and flag unclear claims:\n'+d.source:'Use clear examples and check understanding.'}`}]})).text;}else output=material(d.topic,d.type);const m={id:uid(),title:`${d.type} · ${d.custom||catalog[d.topic].name}`,text:output,at:Date.now(),cards:d.type==='Flashcards'&&!d.source&&!d.custom?catalog[d.topic].terms:null};state.materials.unshift(m);save();showMaterial(m);notify('Your study material is ready.');}));$('#material-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>50000)return notify('Use a text file under 50 KB.');const content=await file.text();if(content.length>12000)return notify('Please use an excerpt under 12,000 characters.');$('#source').value=content;};}
function showMaterial(m){flash={material:m,index:0,back:false};$('#material-result').innerHTML=`<section class="card" style="margin-top:20px"><div class="topline"><h2>${esc(m.title)}</h2>${btn('Download .txt','download-material')}</div>${m.cards?'<div id="flashcard"></div>':`<div class="content">${esc(m.text)}</div>`}<div class="actions" style="margin-top:18px">${btn('Quiz me on this','material-quiz')}${btn('Explain from basics','material-explain')}</div></section>`;if(m.cards)renderFlash();}
function renderFlash(){const c=flash.material.cards[flash.index];$('#flashcard').innerHTML=`<button class="flashcard" data-action="flip"><strong>${esc(flash.back?c[1]:c[0])}</strong><small>${flash.back?'Click to see the prompt':'Click to reveal'} · ${flash.index+1}/${flash.material.cards.length}</small></button><div class="actions" style="margin-top:12px">${btn('← Previous','flash-prev')}${btn('Next →','flash-next')}</div>`;}
function planner(){main.innerHTML=title('A plan you can actually follow.','Prioritise upcoming exams, difficult subjects and topics that need practice.')+`<div class="grid two"><form id="subject-form" class="card"><h2>Add a subject</h2><div class="form-grid">${field('Subject / course','name','','text','required maxlength="80"')}${field('Exam date','exam','','date','required')}${select('Difficulty','difficulty','<option value="1">Easy</option><option value="2" selected>Moderate</option><option value="3">Hard</option>')}${field('Current progress (%)','progress',0,'number','min="0" max="100" required')}</div><label class="check"><input name="weak" type="checkbox">This is a weak area for me</label><button class="primary">Add subject</button></form><section class="card"><h2>Your subjects</h2>${state.subjects.length?state.subjects.map((s,i)=>`<div class="list-row"><div><strong>${esc(s.name)}</strong><small>Exam: ${s.exam} · ${s.progress}% complete${s.weak?' · needs practice':''}</small></div><button data-action="remove-subject" data-index="${i}" aria-label="Remove ${esc(s.name)}">×</button></div>`).join(''):'<p class="empty">Add your first subject and exam date.</p>'}<form id="plan-form">${field('Available hours each day','hours',state.hours,'number','min="0.25" max="12" step="0.25" required')}<button class="primary">${state.plan.length?'Rebalance unfinished plan':'Generate my plan'} ↗</button></form></section></div><div class="section-title"><h2>Your study schedule</h2>${btn('Download plan','export-plan')}</div><div class="card">${state.plan.length?state.plan.slice(0,180).map((p,i)=>`<label class="row-check ${p.done?'done':''}"><input type="checkbox" data-plan="${i}" ${p.done?'checked':''}><span><b>${p.date} · ${esc(p.subject)} · ${p.minutes} min</b><small>${p.task}</small></span></label>`).join(''):'<p class="empty">Your schedule will appear here. Plans cover up to 90 days.</p>'}</div>`;form('subject-form',d=>{try{buildPlan([{...d,id:uid()}],1);state.subjects.push({...d,id:uid(),progress:+d.progress,difficulty:+d.difficulty,weak:d.weak==='on'});save();planner();}catch(e){notify(e.message);}});form('plan-form',d=>{try{const completed=state.plan.filter(p=>p.done);state.hours=+d.hours;state.plan=buildPlan(state.subjects,state.hours).map(p=>({...p,done:completed.some(c=>c.id===p.id&&c.date===p.date)}));save();planner();}catch(e){notify(e.message);}});document.querySelectorAll('[data-plan]').forEach(el=>el.onchange=()=>{const p=state.plan[+el.dataset.plan];p.done=el.checked;if(p.done){event('plan',{xp:5,topic:p.subject},'plan-'+p.id+'-'+p.date);const subject=state.subjects.find(s=>s.name===p.subject);if(subject){const total=state.plan.filter(t=>t.subject===p.subject).length;subject.progress=Math.min(100,Math.max(+subject.progress,Math.round(state.plan.filter(t=>t.subject===p.subject&&t.done).length/total*100)));}}save();el.closest('label').classList.toggle('done',p.done);});}
function focusView(){main.innerHTML=title('One thing at a time.','25 minutes of focus. 5 minutes to recharge.',btn('Back to dashboard','home'))+`<div class="card focus-card"><span class="eyebrow" id="focus-phase">${focus.phase.toUpperCase()}</span><div class="timer" id="focus-clock">${clock(focus.seconds)}</div><label class="field">Current topic<input id="focus-topic" value="${esc(focus.topic)}" placeholder="For example: Python loops" maxlength="100"></label><label class="field">My goal for this session<input id="focus-goal" value="${esc(focus.goal)}" placeholder="Complete three practice questions" maxlength="200"></label><div class="actions">${btn(focus.running?'Pause':'Start focusing','focus-toggle','primary')}${btn('Reset','focus-reset')}${btn('Ask MindMate','focus-ai')}</div><p class="muted" style="margin-top:20px">Breaks start automatically. Keep this page open for reminders.</p></div>`;$('#focus-topic').oninput=e=>focus.topic=e.target.value;$('#focus-goal').oninput=e=>focus.goal=e.target.value;}
function clock(s){return String(Math.floor(s/60)).padStart(2,'0')+':'+String(Math.floor(s%60)).padStart(2,'0');}
setInterval(()=>{if(focus.running){focus.seconds=Math.max(0,Math.ceil((focus.deadline-Date.now())/1000));if(!focus.seconds){if(focus.phase==='Focus'){event('focus',{seconds:1500,xp:15,topic:focus.topic},focus.cycle);focus.phase='Break';focus.seconds=300;notify('Focus complete. Take a five-minute break.');}else{focus.phase='Focus';focus.seconds=1500;focus.cycle=uid();notify('Break complete. Ready for your next focus session.');}focus.deadline=Date.now()+focus.seconds*1000;if(page==='focus')focusView();}if($('#focus-clock'))$('#focus-clock').textContent=clock(focus.seconds);}},1000);
function progress(){const a=analytics(state.events);const badges=[['First step',state.sessions.length>0],['Finding your rhythm',a.xp>=100],['Seven-day streak',a.streak>=7],['Concept master',Object.values(a.topics).some(t=>t.attempts>=3&&t.correct/t.attempts>=.8)],['Coding champion',state.events.filter(e=>e.topic==='code'&&e.correct).length>=3],['Team learner',state.events.some(e=>e.type==='team')]];main.innerHTML=title('See how far you’ve come.','Your insights come from recorded activities, not estimated AI scores.')+stats(a)+`<div class="grid two"><section class="card"><h2>Topic confidence</h2>${Object.keys(a.topics).length?Object.entries(a.topics).map(([t,s])=>{const pct=Math.round(s.correct/s.attempts*100),label=s.attempts<3?'Developing':pct>=80?'Strong':pct>=60?'Developing':'Needs practice';return `<div class="list-row"><div style="width:100%"><strong>${esc(catalog[t]?.name||t)} <span class="tag ${label==='Strong'?'green':label==='Developing'?'amber':'red'}">${label}</span></strong><div class="progress-bar"><span style="width:${pct}%"></span></div><small>${s.correct}/${s.attempts} correct · ${pct}%</small></div></div>`;}).join(''):'<p class="empty">Take a quiz to discover your strong and developing areas.</p>'}</section><section class="card"><h2>Last seven days</h2><div class="chart">${Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));const es=state.events.filter(e=>new Date(e.at).toLocaleDateString('en-CA')===d.toLocaleDateString('en-CA'));const xp=es.reduce((a,e)=>a+(e.xp||0),0);return `<div class="chart-col"><span>${xp} XP</span><div class="chart-bar" style="height:${Math.min(95,xp)}px"></div>${d.toLocaleDateString(undefined,{weekday:'short'})}</div>`;}).join('')}</div><p class="muted">Level ${Math.floor(a.xp/100)+1} · ${100-a.xp%100} XP to the next level</p></section></div><div class="section-title"><h2>Your milestones</h2></div><div class="grid">${badges.map(([b,done])=>`<div class="card"><span class="tag ${done?'green':''}">${done?'✓ Earned':'○ In progress'}</span><h3 style="margin:12px 0 0">${b}</h3></div>`).join('')}</div><section class="card" style="margin-top:20px"><h2>Recommended next steps</h2>${recommendations(a)}</section>`;}
function history(){main.innerHTML=title('Your learning journal.',memory?'Saved in this browser.':'Available for this visit. Enable personal memory to keep sessions.')+`${state.sessions.length?state.sessions.map((s,i)=>`<button class="option" data-action="session" data-index="${i}"><b>${esc(s.title)}</b><br><span class="muted">${new Date(s.date).toLocaleString()} · ${modes[s.mode]?.name||'Viva'} · ${s.messages.length} messages</span></button>`).join(''):'<p class="empty">Your next learning breakthrough could start here.</p>'}`;}
function profileForm(){const p=me?.profile||{};return `<form id="profile-form" class="card"><h2>Your study profile</h2><p class="muted">Use a nickname. Only profiles with discovery enabled appear to other learners on this server.</p><div class="form-grid">${field('Nickname','name',p.name||'','','required maxlength="40"')}${field('Course','course',p.course||'','','required maxlength="80"')}${field('Subject','subject',p.subject||'','','required maxlength="60"')}${field('Topic','topic',p.topic||'','','required maxlength="80"')}${select('Learning level','level',options(['Beginner','Intermediate','Advanced'],p.level))}${select('Meeting preference','preference',options(['Online','In person','Either'],p.preference))}${field('Study goal','goal',p.goal||'','','required maxlength="100"')}${field('Time zone','timezone',p.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone,'text','required maxlength="60"')}${field('Available from','start',p.start||'19:00','time','required')}${field('Available until','end',p.end||'21:00','time','required')}</div><div class="actions">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<label class="check"><input type="checkbox" name="days" value="${d}" ${(p.days||['Mon','Wed','Fri']).includes(d)?'checked':''}>${d}</label>`).join('')}</div><label class="check"><input type="checkbox" name="discoverable" ${p.discoverable?'checked':''}>Show my study profile in partner search</label><button class="primary">Save profile</button></form>`;}
function wireProfile(){form('profile-form',(d,f)=>task(async()=>{d.days=new FormData(f).getAll('days');d.discoverable=d.discoverable==='on';me.profile=(await api('/api/profile',d)).profile;$('#avatar').textContent=me.profile.name[0].toUpperCase();notify('Your profile is saved.');}));}
function buddies(){main.innerHTML=title('Find your kind of study buddy.','Match on subjects, goals, level and overlapping availability.')+`<div class="grid two">${profileForm()}<section class="card"><h2>Your invitations</h2><div id="invitations"><p class="muted">Loading…</p></div><div class="notice">Profiles are real learners registered on this server. The directory starts empty. Time overlap is compared only within the same time zone.</div></section></div><div class="section-title"><h2>Compatible learners</h2></div><form id="buddy-search" class="actions"><label class="field" style="flex:1">Filter by subject, course, topic, goal or level<input name="query" maxlength="100" placeholder="For example: Calculus or Beginner"></label><button class="primary">Find matches</button></form><div id="buddy-results" class="grid"></div>`;wireProfile();form('buddy-search',d=>task(()=>loadBuddies(d.query)));loadBuddies('').catch(e=>notify(e.message));}
async function loadBuddies(q){const out=await api('/api/buddies?q='+encodeURIComponent(q));if(page!=='buddies')return;$('#invitations').innerHTML=out.invitations.length?out.invitations.map((i,n)=>`<div class="list-row"><div><strong>${esc(i.name)}</strong><small>Invited by ${esc(i.from)}</small></div><button class="secondary" data-action="accept-invite" data-room="${esc(i.room)}" data-invite="${esc(i.invite)}">Join</button></div>`).join(''):'<p class="empty">No invitations yet. Create a room and invite a friend.</p>';$('#buddy-results').innerHTML=out.buddies.length?out.buddies.map(b=>`<div class="card"><span class="tag green">${b.score}% compatibility</span><h2 style="margin-top:14px">${esc(b.name)}</h2><p class="sub">${esc(b.course)} · ${esc(b.subject)}<br>${esc(b.topic)} · ${esc(b.level)}</p><p class="muted">${esc(b.days.join(', '))} · ${b.start}–${b.end}<br>${esc(b.timezone)} · ${esc(b.preference)}</p><p class="sub">${esc(b.goal)}</p><div>${b.reasons.map(r=>`<span class="tag">${r}</span>`).join('')}</div><button class="primary" style="margin-top:15px" data-action="invite-buddy" data-user="${b.id}">Invite to a room ↗</button></div>`).join(''):'<div class="card wide"><p class="empty">No compatible profiles found yet. Save your profile, invite a friend to this server, and search again.</p></div>';}
function rooms(){main.innerHTML=title('A shared space to make progress.','Bring your friends, your questions and one clear goal.')+`<div class="grid two"><form id="create-room" class="card"><h2>Create a study room</h2>${field('Room name','name','','text','required maxlength="80" placeholder="Evening revision club"')}${field('Shared topic','topic','','text','required maxlength="100" placeholder="Linear equations"')}${field('Today’s goal','goal','','text','required maxlength="200" placeholder="Complete five practice problems"')}${field('Goal target (number of tasks)','target',5,'number','required min="1" max="1000"')}<button class="primary">Create room ↗</button></form><section class="card"><h2>Join your friends</h2><p class="sub">Paste an invitation link. Anyone with a valid invitation can join that room.</p><form id="join-room">${field('Invitation link','link','','url','required placeholder="http://localhost:3040/room/…#invite=…"')}<button class="secondary">Join room</button></form><div class="notice">${config.local?'Running locally: invitations work in browsers on this computer. Hosting is needed for friends on other devices.':'Rooms are available to learners who can reach this server.'}</div></section></div><div class="section-title"><h2>Your rooms</h2></div><div class="grid" id="room-list"><p class="muted">Loading rooms…</p></div>`;form('create-room',d=>task(async()=>{const out=await api('/api/rooms',d);room=out.room;event('team',{xp:0},'team-'+room.id);busy=false;view('room');}));form('join-room',d=>{try{const u=new URL(d.link);if(u.origin!==location.origin)throw new Error('Open this invitation on its original server: '+u.origin);join(u.pathname.split('/').at(-1),new URLSearchParams(u.hash.slice(1)).get('invite'));}catch(e){notify(e.message);}});api('/api/rooms').then(o=>{if(page==='rooms')$('#room-list').innerHTML=o.rooms.length?o.rooms.map(r=>`<button class="card mode-card" data-action="open-room" data-room="${r.id}"><span class="card-icon">♧</span><h3>${esc(r.name)}</h3><p>${esc(r.topic)}<br>${r.members} members</p><span class="link">Enter room →</span></button>`).join(''):'<p class="empty">Create your first study room to get started.</p>';}).catch(e=>notify(e.message));}
async function join(rid,invite){await task(async()=>{room=(await api('/api/join',{room:rid,invite})).room;event('team',{xp:0},'team-'+room.id);window.history.replaceState({},'','/');busy=false;view('room');});}
async function openRoom(rid){await task(async()=>{room=(await api('/api/rooms/'+rid)).room;busy=false;view('room');});}
function roomView(){if(!room)return view('rooms');notesVersion=room.notesVersion;notesDirty=false;main.innerHTML=title(esc(room.name),esc(room.topic),btn('Invite link','room-link')+btn('Leave room','room-leave'))+`<div class="room-grid"><div class="stack"><section class="card"><h2>Group conversation</h2><div id="room-people" class="muted"></div><div class="room-chat" id="room-chat" role="log" aria-label="Group chat"></div><form id="room-message"><label class="field">Message the group<textarea name="text" maxlength="3000" required placeholder="Share a question or an idea…"></textarea></label><div class="actions"><button class="primary">Send to group</button><button type="button" class="secondary" data-action="room-ai">Ask shared AI</button></div></form><p id="room-sync" class="muted" role="status" style="margin:12px 0 0">Connected · updates every 3 seconds</p></section><section class="card"><h2>Collaborative notes</h2><label class="field">Shared notes<textarea id="room-notes" maxlength="20000" rows="7">${esc(room.notes)}</textarea></label><div class="actions">${btn('Save notes','room-notes','primary')}${btn('Load latest notes','room-notes-load')}</div><p class="muted">Edits are checked for conflicts before saving.</p></section></div><div class="stack"><section class="card"><h2>Today’s shared goal</h2><p>${esc(room.goal)}</p><div id="room-goal"></div><h3 style="margin-top:20px">Shared Pomodoro</h3><div id="room-timer"></div></section><section class="card"><h2>Group quiz</h2><div id="room-quiz"></div><div id="room-leaderboard"></div></section></div></div>`;$('#room-notes').oninput=()=>notesDirty=true;form('room-message',d=>task(async()=>{await roomAction('message',{text:d.text});$('#room-message').reset();}));updateRoom();roomPoll=setInterval(async()=>{if(page!=='room')return;try{const out=await api('/api/rooms/'+room.id);if(page!=='room'||out.room.id!==room.id)return;room=out.room;updateRoom();$('#room-sync').textContent='Connected · updates every 3 seconds';}catch(e){if($('#room-sync'))$('#room-sync').textContent='Connection interrupted. Retrying… '+e.message;}},3000);}
function updateRoom(){if(page!=='room'||!$('#room-chat'))return;const owner=room.owner===me.id;$('#room-people').textContent=room.members.map(m=>m.name+(m.online?' · online':'')).join('  /  ');const list=$('#room-chat'),atBottom=list.scrollHeight-list.scrollTop-list.clientHeight<80;const content=room.messages.map(m=>`<div class="message"><span class="sender">${esc(m.name)}${m.ai?' · SHARED AI':''}</span>${esc(m.text)}</div>`).join('')||'<p class="empty">Say hello and share what you’re working on.</p>';if(list.innerHTML!==content){list.innerHTML=content;if(atBottom)list.scrollTop=list.scrollHeight;}$('#room-goal').innerHTML=`<b>${room.completed} / ${room.target} tasks completed</b><div class="progress-bar"><span style="width:${room.completed/room.target*100}%"></span></div>${owner?btn('−','room-goal-minus')+' '+btn('Task completed +','room-goal-plus'):''}`;$('#room-timer').innerHTML=`<div class="muted">${room.timer.phase} · ${room.timer.running?'Running':'Paused'}</div><div class="room-timer">${clock(room.timer.remaining)}</div>${owner?`<div class="actions">${btn(room.timer.running?'Pause':'Start','room-timer-toggle','primary')}${btn('Reset','room-timer-reset')}</div>`:'<p class="muted">The host controls the shared timer.</p>'}`;
 const q=room.quiz;const html=q?`<p>${esc(q.question)}</p>${q.options.map((o,i)=>`<button class="option ${q.closed&&i===q.correct?'correct':''}" data-action="room-answer" data-index="${i}" ${q.answered||q.closed?'disabled':''}>${q.yourAnswer?.choice===i?'● ':''}${esc(o)}</button>`).join('')}<p class="muted">${q.answeredCount} answered${q.answered?' · Your answer is locked':''}</p>${q.closed?`<div class="notice">${esc(q.explanation)}</div>`:owner?btn('End round & reveal','room-reveal'):''}`:'<p class="sub">Everyone answers independently. Results appear when the host ends the round.</p>';
 const quizKey=JSON.stringify(q)+owner;if($('#room-quiz').dataset.key!==quizKey){$('#room-quiz').dataset.key=quizKey;$('#room-quiz').innerHTML=html+(owner&&(!q||q.closed)?`<label class="field">Next quiz topic<select id="room-quiz-topic">${topicOptions()}</select></label>${btn('Start quiz round','room-quiz-start','primary')}`:'');}
 $('#room-leaderboard').innerHTML=room.leaderboard.length?'<h3 style="margin-top:20px">Leaderboard</h3>'+room.leaderboard.map(s=>`<div class="score"><span>${esc(s.name)}<br><small>${s.correct}/${s.attempts} correct${Object.keys(s.weak).length?' · Review: '+Object.keys(s.weak).map(k=>catalog[k].name).join(', '):''}</small></span><b>${s.points} pts</b></div>`).join(''):'';
 if(!notesDirty&&document.activeElement!==$('#room-notes')){$('#room-notes').value=room.notes;notesVersion=room.notesVersion;}}
async function roomAction(action,body={}){const out=await api('/api/rooms/'+room.id+'/'+action,body);if(out.room){room=out.room;updateRoom();}return out;}
function privacy(){main.innerHTML=title('Your learning. Your choice.','Choose what to remember and what to share.')+`<div class="grid two">${profileForm()}<div class="stack"><section class="card"><h2>Personal memory</h2><label class="check"><input id="memory" type="checkbox" ${memory?'checked':''}>Remember my learning on this browser</label><p class="sub">Off by default. Turning it off removes the saved browser copy of conversations, materials, plans and progress. This visit remains available until you close or refresh.</p></section><section class="card"><h2>Data & privacy</h2><p class="sub">Your study profile and rooms are saved on this server so other participants can collaborate. Your session cookie identifies this browser. Discovery is opt-in.</p><p class="sub">Live AI sends your questions, pasted material, images or selected room discussion to OpenAI. Built-in lessons do not. No advertising analytics are collected.</p><p class="muted">Deleting your server identity removes your profile and chat messages. Collaborative notes remain for other members. AI provider retention is separate. Clearing cookies loses access to your guest identity.</p><div class="actions">${btn('Export all my data','export')}${btn('Delete personal learning','delete-local')}${btn('Delete community identity','delete-server','secondary danger')}</div></section></div></div>`;wireProfile();$('#memory').onchange=e=>{memory=e.target.checked;try{localStorage.setItem('mindmate-memory',String(memory));if(!memory){localStorage.removeItem('mindmate-data');localStorage.removeItem('guideai-data');localStorage.removeItem('guideai-memory');}}catch{}save();notify(memory?'Personal memory enabled.':'Saved personal memory removed.');};}
async function upload(){const file=$('#image-file').files[0];if(!file)return;if(file.size>3*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))return notify('Use a JPG, PNG or WebP under 3 MB.');await task(async()=>{notify('Reading the question…');const image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});const result=await api('/api/image',{image});modal('<h2>Did I read it correctly?</h2><label class="field">Edit the extracted question<textarea id="extracted" rows="7"></textarea></label>'+btn('Use this question','use-image','primary'));$('#extracted').value=result.text;notify('Check the extracted question before continuing.');});}
function handle(a,b){if(busy)return notify('Please wait for the current request.');if(['home','studio','practice','materials','planner','focus','buddies','rooms','progress','privacy'].includes(a))return view(a);
 if(a==='teacher')return switchMode('teacher');
 if(a==='hint'||a==='solution')return send(a==='hint'?'Give me a hint.':'Show me the solution.',a);
 if(a==='similar'){if(session.state){const s=session.state;return startLesson(s.topic,Math.max(1,Math.min(3,s.difficulty+(s.solved&&!s.revealed&&s.attempts<3?1:-1))));}return send('Give me a similar practice problem adapted to my demonstrated understanding. Wait for my attempt.');}
 if(a==='teach'){if(session.state){session.state.teach=true;session.messages.push({role:'assistant',text:'Explain the concept in your own words, including why the method works. I’ll check the key ideas.'});saveSession();return chat();}return send('Ask me to teach this concept back. Evaluate accuracy, missing concepts and misconceptions after I explain.');}
 if(a==='recap'){if(session.state){session.messages.push({role:'assistant',text:catalog[session.state.topic].explanation});saveSession();return chat();}return send('Give me a concise concept recap and one question to check understanding.');}
 if(a==='summary')return summary();
 if(a==='download-session')return download('mindmate-session.txt',session.title+'\n\n'+session.messages.map(m=>m.role.toUpperCase()+': '+m.text).join('\n\n'));
 if(a==='ai-summary'){$('#dialog').close();return send('Summarize what I learned, mistakes evident in my attempts, and one next step. Do not invent accuracy or duration.');}
 if(a==='session'){session=state.sessions[+b.dataset.index];session.activeAt=Date.now();return view('chat');}
 if(a==='quiz-answer')return quizAnswer(+b.dataset.index);
 if(a==='quiz-next'){quiz.index++;return renderQuiz();}
 if(a==='quiz-teacher'){mode='teacher';return startLesson(quiz.topic);}
 if(a==='open-material')return showMaterial(state.materials[+b.dataset.index]);
 if(a==='download-material')return download('mindmate-material.txt',flash.material.text);
 if(a==='flip'){flash.back=!flash.back;return renderFlash();}
 if(a==='flash-next'||a==='flash-prev'){flash.index=(flash.index+(a==='flash-next'?1:flash.material.cards.length-1))%flash.material.cards.length;flash.back=false;return renderFlash();}
 if(a==='material-quiz'||a==='material-explain'){mode=a==='material-quiz'?'mentor':'teacher';return startQuestion((a==='material-quiz'?'Quiz me one question at a time on this material.':'Explain this material from the basics:')+'\n'+flash.material.text);}
 if(a==='remove-subject'){const s=state.subjects.splice(+b.dataset.index,1)[0];state.plan=state.plan.filter(p=>p.subject!==s.name);save();return planner();}
 if(a==='export-plan')return download('mindmate-study-plan.txt',state.plan.map(p=>`${p.done?'[x]':'[ ]'} ${p.date} | ${p.subject} | ${p.minutes} min | ${p.task}`).join('\n'));
 if(a==='focus-toggle'){if(!focus.running){focus.running=true;focus.deadline=Date.now()+focus.seconds*1000;focus.cycle??=uid();}else focus.running=false;document.body.classList.toggle('focus-active',focus.running);return focusView();}
 if(a==='focus-reset'){focus={...focus,running:false,seconds:1500,phase:'Focus',cycle:uid()};document.body.classList.remove('focus-active');return focusView();}
 if(a==='focus-ai'){mode='mentor';return startQuestion(`Help me take one small step toward my study goal: ${focus.goal||'understand the concept'}. Topic: ${focus.topic||'ask me what I am studying'}.`);}
 if(a==='image')return $('#image-file').click();
 if(a==='use-image'){const text=$('#extracted').value.trim();if(!text)return;$('#dialog').close();return startQuestion(text);}
 if(a==='open-room')return openRoom(b.dataset.room);
 if(a==='accept-invite')return join(b.dataset.room,b.dataset.invite);
 if(a==='invite-buddy')return task(async()=>{const rooms=(await api('/api/rooms')).rooms;if(!rooms.length)return notify('Create a study room first, then invite your buddy.');modal('<h2>Invite to your room</h2><p>Choose a room you own.</p><form id="invite-form">'+select('Study room','room',rooms.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join(''))+'<button class="primary">Send invitation</button></form>');form('invite-form',d=>task(async()=>{await api('/api/rooms/'+d.room+'/invite',{userId:b.dataset.user});$('#dialog').close();notify('Invitation sent.');}));});
 if(a==='room-link')return task(async()=>{const out=await roomAction('link');modal('<h2>Invite someone to study</h2><p>Anyone with this link can join the room.</p><label class="field">Room invitation<input id="invite-link" readonly></label>'+btn('Copy link','copy-link','primary'));$('#invite-link').value=out.link;});
 if(a==='copy-link')return task(async()=>{try{await navigator.clipboard.writeText($('#invite-link').value);notify('Invitation copied.');}catch{$('#invite-link').select();notify('Select and copy the invitation link.');}});
 if(a==='room-notes')return task(async()=>{await roomAction('notes',{notes:$('#room-notes').value,version:notesVersion});notesDirty=false;notesVersion=room.notesVersion;notify('Shared notes saved.');});
 if(a==='room-notes-load'){modal('<h2>Latest shared notes</h2><p>Your editor draft stays unchanged. Copy anything you need before merging.</p><div class="content">'+esc(room.notes)+'</div>'+btn('Use latest as my draft','notes-replace')+btn('Keep my draft, mark as merged','notes-merge'));return;}
 if(a==='notes-replace'||a==='notes-merge'){if(a==='notes-replace')$('#room-notes').value=room.notes;notesVersion=room.notesVersion;notesDirty=true;$('#dialog').close();return;}
 if(a==='room-goal-plus'||a==='room-goal-minus')return task(()=>roomAction('goal',{delta:a==='room-goal-plus'?1:-1}));
 if(a==='room-timer-toggle'||a==='room-timer-reset')return task(()=>roomAction('timer',{command:a==='room-timer-reset'?'reset':room.timer.running?'pause':'start'}));
 if(a==='room-quiz-start')return task(()=>roomAction('quiz',{topic:$('#room-quiz-topic').value}));
 if(a==='room-answer')return task(()=>roomAction('answer',{quiz:room.quiz.id,answer:+b.dataset.index}));
 if(a==='room-reveal')return task(()=>roomAction('reveal'));
 if(a==='room-ai')return task(async()=>{const input=$('#room-message textarea');if(!input.value.trim())return notify('Type a question for the shared AI first.');notify('MindMate is preparing a response for the group…');await roomAction('ai',{text:input.value,mode:'teacher'});input.value='';notify('MindMate answered the group.');});
 if(a==='room-leave'){modal('<h2>Leave this room?</h2><p>If you are the last member, the room will be removed.</p>'+btn('Leave room','confirm-leave','primary'));return;}
 if(a==='confirm-leave')return task(async()=>{await roomAction('leave');clearInterval(roomPoll);room=null;$('#dialog').close();busy=false;view('rooms');});
 if(a==='export')return task(async()=>download('mindmate-data.json',JSON.stringify({personal:state,community:await api('/api/export')},null,2),'application/json'));
 if(a==='delete-local'||a==='delete-server'){modal(`<h2>${a==='delete-local'?'Delete personal learning data?':'Delete your community identity?'}</h2><p>${a==='delete-local'?'This removes conversations, materials, plans and progress from this browser.':'Your profile, room membership and authored chat messages will be removed from the server. Shared notes remain for other members.'}</p>${btn('Delete permanently',a==='delete-local'?'confirm-local':'confirm-server','primary')}`);return;}
 if(a==='confirm-local'){state={events:[],sessions:[],materials:[],subjects:[],plan:[],hours:2,goals:[]};session=null;for(const k of ['mindmate-data','guideai-data','guideai-memory'])localStorage.removeItem(k);save();$('#dialog').close();notify('Personal learning data deleted.');return;}
 if(a==='confirm-server')return task(async()=>{await api('/api/delete',{});me=await api('/api/session',{});room=null;$('#dialog').close();busy=false;view('privacy');notify('Community identity deleted. A new anonymous session is ready.');});
}
async function init(){try{[config,me]=await Promise.all([api('/api/config'),api('/api/session',{})]);$('#connection').textContent=config.live?'● AI key configured':'● Built-in learning';$('#connection').title='A configured key does not verify API credits.';$('#avatar').textContent=(me.profile?.name||'M')[0].toUpperCase();save();const rid=location.pathname.match(/^\/room\/([\w-]+)$/)?.[1],invite=new URLSearchParams(location.hash.slice(1)).get('invite');if(rid&&invite){main.innerHTML=title('You’re invited to a study room.','Joining shares your nickname with room members.')+btn('Join study room','accept-invite','primary');const b=$('[data-action="accept-invite"]');b.dataset.room=rid;b.dataset.invite=invite;}else if(rid)openRoom(rid);else view('home');}catch(e){main.innerHTML=title('Could not connect to MindMate.',esc(e.message))+'<p>Start the server using START-MINDMATE.cmd, then refresh this page.</p>';}}
init();

